  async function write(transform,prejoin=false){if(isBusy())throw new Error('请等待当前回复与变量更新结束。');if(health.writeBlocked)throw new Error('变量保存曾被校验器改变，请先检查原卡与MVU，再重新启用脚本。');const fresh=read();if(!fresh?.data||!(prejoin?relevant(fresh):C.member(fresh.data.stat_data)))throw new Error('当前身份或聊天记录尚未确认。');const before=C.clone(fresh.data),after=transform(C.clone(before));if(!after)return false;if(read()?.fingerprint!==fresh.fingerprint)throw new Error('聊天或回复分支已切换，本次操作未写入。');writing=true;try{await M().replaceMvuData(after,{type:'message',message_id:fresh.last.message_id});const saved=read();if(saved?.fingerprint!==fresh.fingerprint){ui.notice='原聊天保存后已切换，请在对应分支核对记录。';return false;}if(JSON.stringify(saved.data?.stat_data?.万法宗)!==JSON.stringify(after.stat_data.万法宗)||JSON.stringify(saved.data?.stat_data?.主角)!==JSON.stringify(after.stat_data.主角)){health.writeBlocked=true;try{await M().replaceMvuData(before,{type:'message',message_id:fresh.last.message_id});}catch{}throw new Error('原卡校验器未完整保留万法宗记录，已停止继续结算并尝试还原，请检查MVU日志。');}current=saved;api('eventEmit')?.('daoyuan_mvu_manual_updated');return true;}finally{writing=false;}}
